gatewayHttpStatus: 500
providerRequests: 10
repairRequests: 0
toolCallRequests: 0
toolResultRequests: 0
userFacingOutput: generic failure
diagnostics: omitted on base
argumentTextInGatewayLogs: false

$ node proof-live.mjs --expect-present
testedHead: 8bcab00993c6f2b81b431ea198d9493268f1832b
gatewayHttpStatus: 200
providerRequests: 8
malformedRequests: 2
repairRequests: 2
toolCallRequests: 2
toolResultRequests: 2
userFacingOutput: Recovered after reading the local proof file.
diagnostics: argumentChars=19 argumentHash=jiqoxq1e07seo repairAttempted=true
argumentTextInGatewayLogs: false

$ pnpm test src/agents/embedded-agent-helpers/error-text.test.ts src/agents/embedded-agent-runner/run/assistant-failure.test.ts --maxWorkers=1
