    response.writeHead(404).end();
    return;
  }
  const buffers: Buffer[] = [];
  for await (const buffer of request) buffers.push(Buffer.from(buffer));
  const body = Buffer.concat(buffers).toString("utf8");
  const payload = JSON.parse(body) as {
    model?: string;
    input?: string | Array<string | { text?: string }>;
  };
  const values = Array.isArray(payload.input) ? payload.input : [payload.input ?? ""];
  const texts = values.map((value) =>
    typeof value === "string" ? value : String(value.text ?? JSON.stringify(value)),
