    row.vectorDimensions = (result.data ?? []).map((item) => item.embedding?.length ?? 0);
    if (row.vectorDimensions.length !== texts.length || row.vectorDimensions.some((size) => size !== 1024)) {
      response.writeHead(502, { "content-type": "application/json" });
      response.end(JSON.stringify({ error: { message: "local model returned unexpected embedding dimensions" } }));
      return;
    }
    response.writeHead(upstream.status, { "content-type": "application/json" }).end(upstreamBody);
  } catch (error) {
    row.upstreamStatus = 502;
    response.writeHead(502, { "content-type": "application/json" });
    response.end(JSON.stringify({ error: { message: error instanceof Error ? error.message : String(error) } }));
  }
});
